import java.time.LocalDate
import scala.math.Ordering

final case class Effectivity(from: LocalDate, until: Option[LocalDate] = None) {
  def effectiveOn(asOf: LocalDate)(implicit o: Ordering[LocalDate]): Boolean =
    o.gteq(asOf, from) && until.forall(u => o.lt(asOf, u))       // [from, until)
}

implicit val localDateOrdering: Ordering[LocalDate] = Ordering.by(_.toEpochDay)

